create table wksp_dtesc.sgt_cat_ot_estado (
    id              number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by 1 cache
    20 noorder nocycle nokeep noscale not null enable,
    codigo          varchar2(30 byte) not null enable,
    nombre          varchar2(100 byte) not null enable,
    nivel_orden     number not null enable,
    es_final        char(1 byte) default 'N' not null enable,
    activo          char(1 byte) default 'Y' not null enable,
    creado_por      varchar2(255 byte),
    creado_el       timestamp(6) default systimestamp,
    actualizado_por varchar2(255 byte),
    actualizado_el  timestamp(6)
);

alter table wksp_dtesc.sgt_cat_ot_estado
    add constraint chk_sgt_cat_ot_est_act
        check ( activo in ( 'Y', 'N' ) ) enable;

alter table wksp_dtesc.sgt_cat_ot_estado
    add constraint chk_sgt_cat_ot_est_fin
        check ( es_final in ( 'Y', 'N' ) ) enable;

alter table wksp_dtesc.sgt_cat_ot_estado add constraint uq_sgt_cat_ot_est_cod unique ( codigo )
    using index enable;

alter table wksp_dtesc.sgt_cat_ot_estado add constraint uq_sgt_cat_ot_est_nom unique ( nombre )
    using index enable;

alter table wksp_dtesc.sgt_cat_ot_estado add primary key ( id )
    using index enable;


